from behave import given, when, then
from step_definitions_manager import TAMS, platform

@platform("TAMS-203")
@TAMS([203])
@when('the gear is shifted to "{gear}"')
def step_impl(context, gear):
    try:
        block_to_add = ""
        valid_gears = {"park": "P", "reverse": "R", "neutral": "N", "drive": "D"}

        if gear not in valid_gears:
            raise ValueError("Unsupported gear position: " + gear)

        parameters = {
            "String": {
                "Variable": ["", context.signal.calalogue.get_key_value("gear_position"), "in",]
            },
            "String": {"EnumValue": ["", valid_gears[gear], "in"]},
            "Float": {"PostDelay": ["", "0.8", "in"]},
        }
    block_to_add += context.test_exec_gen.get_library_call(
        block_type = "Non Frame",
        name= "gear_" + gear,
        lib_reference = context.api_calalogue.get_key_value("set_enum_signal"),
        arguments= parameters,
    )

    except Exception as err:
        raise err

    context.xml_block_to_add = block_to_add
    context.signals_used.append("gear_position")

